-- LTMS schema for PostgreSQL 15+.
-- GENERATED by `python -m scripts.dump_schema` from server/models. Do not edit by hand.
--
-- Apply to an empty database as the ltms owner:
--   psql -v ON_ERROR_STOP=1 -d ltms -f config/schema.sql
--
-- `records` holds signed chain headers and is append-only (triggers below
-- block UPDATE and TRUNCATE, and DELETE unless the record's tombstone in
-- `record_tombstones` already exists). `record_tombstones` is append-only.
-- `record_payloads` may be purged by retention; the chain still verifies.

BEGIN;

CREATE TABLE admin_users (
	id UUID NOT NULL, 
	username VARCHAR(64) NOT NULL, 
	password_hash TEXT NOT NULL, 
	last_login_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (username)
);

CREATE TABLE catalog_integrations (
	id UUID NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	base_url TEXT NOT NULL, 
	credential_env VARCHAR(64), 
	description TEXT, 
	created_by VARCHAR(64) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_catalog_integrations_kind CHECK (kind IN ('http', 's3', 'huggingface', 'ollama', 'openai', 'mcp')), 
	UNIQUE (name)
);

CREATE TABLE declared_locations (
	id SERIAL NOT NULL, 
	subject_type VARCHAR(8) NOT NULL, 
	subject_name VARCHAR(64) NOT NULL, 
	label VARCHAR(80) NOT NULL, 
	room VARCHAR(40), 
	lat FLOAT, 
	lon FLOAT, 
	updated_by VARCHAR(64) NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_declared_locations_subject UNIQUE (subject_type, subject_name), 
	CONSTRAINT ck_declared_locations_subject_type CHECK (subject_type IN ('member', 'swarm'))
);

CREATE TABLE directives (
	id UUID NOT NULL, 
	scope_swarm_id VARCHAR(64), 
	text TEXT NOT NULL, 
	payload JSONB, 
	issued_by VARCHAR(128) NOT NULL, 
	issued_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	statement TEXT NOT NULL, 
	signature VARCHAR(128) NOT NULL, 
	signer VARCHAR(16) NOT NULL, 
	cancelled_at TIMESTAMP WITH TIME ZONE, 
	cancel_statement TEXT, 
	cancel_signature VARCHAR(128), 
	inherited BOOLEAN NOT NULL, 
	confirmed_by VARCHAR(128), 
	PRIMARY KEY (id), 
	CONSTRAINT ck_directives_status CHECK (status IN ('open', 'cancelled'))
);

CREATE INDEX idx_directives_issued_at ON directives (issued_at);

CREATE TABLE lrs_endpoints (
	id UUID NOT NULL, 
	name VARCHAR(64) NOT NULL, 
	url TEXT NOT NULL, 
	xapi_version VARCHAR(8) NOT NULL, 
	auth_type VARCHAR(16) NOT NULL, 
	username TEXT NOT NULL, 
	secret_enc BYTEA, 
	scope JSONB, 
	enabled BOOLEAN NOT NULL, 
	cursor BIGINT NOT NULL, 
	send_reads BOOLEAN DEFAULT true NOT NULL, 
	last_read_id BIGINT DEFAULT '0' NOT NULL, 
	last_success_at TIMESTAMP WITH TIME ZONE, 
	last_error_at TIMESTAMP WITH TIME ZONE, 
	last_error TEXT, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);

CREATE TABLE mcp_tokens (
	id UUID NOT NULL, 
	name VARCHAR(64) NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	scope JSONB NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE, 
	revoked_at TIMESTAMP WITH TIME ZONE, 
	last_used_at TIMESTAMP WITH TIME ZONE, 
	owner VARCHAR(128), 
	purpose VARCHAR(500), 
	use_count INTEGER DEFAULT '0' NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_mcp_tokens_name UNIQUE (name), 
	CONSTRAINT uq_mcp_tokens_token_hash UNIQUE (token_hash)
);

CREATE TABLE members (
	id UUID NOT NULL, 
	public_key BYTEA NOT NULL, 
	name VARCHAR(64) NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	operator TEXT, 
	note TEXT, 
	permissions JSONB NOT NULL, 
	requested_permissions JSONB NOT NULL, 
	scope JSONB, 
	status VARCHAR(16) NOT NULL, 
	request_ip VARCHAR(64), 
	enrolled_at TIMESTAMP WITH TIME ZONE, 
	revoked_at TIMESTAMP WITH TIME ZONE, 
	last_seen_at TIMESTAMP WITH TIME ZONE, 
	last_ack_seq BIGINT NOT NULL, 
	last_hash VARCHAR(64) NOT NULL, 
	recall_floor_id BIGINT DEFAULT '0' NOT NULL, 
	memory_generation INTEGER DEFAULT '0' NOT NULL, 
	cognition_admin VARCHAR(16), 
	cognition_declared JSONB, 
	cognition_observed JSONB, 
	intended JSONB, 
	proxied_by VARCHAR(128), 
	ping_requested_at TIMESTAMP WITH TIME ZONE, 
	ping_requested_by VARCHAR(128), 
	ping_delivered_at TIMESTAMP WITH TIME ZONE, 
	specs_declared JSONB, 
	specs_admin JSONB, 
	specs_reported_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_members_kind CHECK (kind IN ('robot', 'agent', 'assistant', 'relay')), 
	CONSTRAINT ck_members_status CHECK (status IN ('pending', 'active', 'revoked', 'rejected')), 
	CONSTRAINT ck_members_cognition_admin CHECK (cognition_admin IS NULL OR cognition_admin IN ('onboard', 'offboard')), 
	UNIQUE (public_key), 
	UNIQUE (name)
);

CREATE TABLE runtime_settings (
	key VARCHAR(64) NOT NULL, 
	value JSONB NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_by VARCHAR(64), 
	PRIMARY KEY (key)
);

CREATE TABLE admin_sessions (
	session_hash BYTEA NOT NULL, 
	admin_id UUID NOT NULL, 
	remote_ip VARCHAR(64), 
	issued_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	revoked_at TIMESTAMP WITH TIME ZONE, 
	last_active_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (session_hash), 
	FOREIGN KEY(admin_id) REFERENCES admin_users (id)
);

CREATE TABLE audit_log (
	id BIGSERIAL NOT NULL, 
	ts TIMESTAMP WITH TIME ZONE NOT NULL, 
	member_id UUID, 
	actor VARCHAR(64), 
	action VARCHAR(32) NOT NULL, 
	detail JSONB NOT NULL, 
	request_id VARCHAR(64), 
	response_count INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(member_id) REFERENCES members (id)
);

CREATE INDEX idx_audit_member_ts ON audit_log (member_id, ts);

CREATE INDEX idx_audit_ts ON audit_log (ts);

CREATE TABLE auth_challenges (
	nonce VARCHAR(64) NOT NULL, 
	member_id UUID NOT NULL, 
	issued_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (nonce), 
	FOREIGN KEY(member_id) REFERENCES members (id)
);

CREATE TABLE datasets (
	id UUID NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	description TEXT, 
	kind VARCHAR(16) NOT NULL, 
	scope VARCHAR(16) DEFAULT 'fleet' NOT NULL, 
	licence TEXT NOT NULL, 
	use VARCHAR(16) DEFAULT 'reference' NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	added_by VARCHAR(64) NOT NULL, 
	approved_by VARCHAR(64), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	integration_id UUID, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_datasets_scope CHECK (scope IN ('fleet')), 
	CONSTRAINT ck_datasets_kind CHECK (kind IN ('upload', 'url', 'integration', 'charter')), 
	CONSTRAINT ck_datasets_status CHECK (status IN ('pending', 'approved', 'retired')), 
	UNIQUE (name), 
	FOREIGN KEY(integration_id) REFERENCES catalog_integrations (id)
);

CREATE TABLE member_addresses (
	id BIGSERIAL NOT NULL, 
	member_id UUID NOT NULL, 
	ip VARCHAR(45) NOT NULL, 
	source VARCHAR(8) NOT NULL, 
	interface VARCHAR(32), 
	first_seen TIMESTAMP WITH TIME ZONE NOT NULL, 
	last_seen TIMESTAMP WITH TIME ZONE NOT NULL, 
	count INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_member_addresses_member_ip_source UNIQUE (member_id, ip, source), 
	FOREIGN KEY(member_id) REFERENCES members (id)
);

CREATE INDEX idx_member_addresses_last_seen ON member_addresses (last_seen);

CREATE TABLE record_tombstones (
	id BIGSERIAL NOT NULL, 
	member_id UUID NOT NULL, 
	agent VARCHAR(64) NOT NULL, 
	seq BIGINT NOT NULL, 
	hash VARCHAR(64) NOT NULL, 
	prev_hash VARCHAR(64) NOT NULL, 
	deleted_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	deleted_by VARCHAR(64) NOT NULL, 
	reason VARCHAR(500), 
	PRIMARY KEY (id), 
	CONSTRAINT uq_record_tombstones_member_seq UNIQUE (member_id, seq), 
	FOREIGN KEY(member_id) REFERENCES members (id), 
	UNIQUE (hash)
);

CREATE OR REPLACE FUNCTION record_tombstones_no_mutation() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'record_tombstones table is append-only: % is not permitted', TG_OP;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_record_tombstones_no_mutation BEFORE UPDATE OR DELETE ON record_tombstones FOR EACH ROW EXECUTE FUNCTION record_tombstones_no_mutation();

CREATE TRIGGER trg_record_tombstones_no_truncate BEFORE TRUNCATE ON record_tombstones FOR EACH STATEMENT EXECUTE FUNCTION record_tombstones_no_mutation();

CREATE TABLE records (
	id BIGSERIAL NOT NULL, 
	member_id UUID NOT NULL, 
	agent VARCHAR(64) NOT NULL, 
	seq BIGINT NOT NULL, 
	ts TIMESTAMP WITH TIME ZONE NOT NULL, 
	type VARCHAR(16) NOT NULL, 
	summary TEXT, 
	place VARCHAR(128), 
	outcome VARCHAR(16), 
	peers JSONB, 
	tags JSONB, 
	refs JSONB, 
	sw VARCHAR(128), 
	prev_hash VARCHAR(64) NOT NULL, 
	payload_hash VARCHAR(64) NOT NULL, 
	hash VARCHAR(64) NOT NULL, 
	sig VARCHAR(128) NOT NULL, 
	header_raw BYTEA NOT NULL, 
	received_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_records_member_seq UNIQUE (member_id, seq), 
	FOREIGN KEY(member_id) REFERENCES members (id), 
	UNIQUE (hash)
);

CREATE INDEX idx_records_outcome ON records (outcome);

CREATE INDEX idx_records_place ON records (place);

CREATE INDEX idx_records_ts ON records (ts);

CREATE INDEX idx_records_type_ts ON records (type, ts);

CREATE OR REPLACE FUNCTION records_no_mutation() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF EXISTS (SELECT 1 FROM record_tombstones t
               WHERE t.member_id = OLD.member_id AND t.seq = OLD.seq AND t.hash = OLD.hash) THEN
      RETURN OLD;
    END IF;
  END IF;
  RAISE EXCEPTION 'records table is append-only: % is not permitted', TG_OP;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_records_no_mutation BEFORE UPDATE OR DELETE ON records FOR EACH ROW EXECUTE FUNCTION records_no_mutation();

CREATE TRIGGER trg_records_no_truncate BEFORE TRUNCATE ON records FOR EACH STATEMENT EXECUTE FUNCTION records_no_mutation();

CREATE TABLE swarms (
	id VARCHAR(64) NOT NULL, 
	name VARCHAR(64) NOT NULL, 
	description TEXT, 
	public_key BYTEA NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	is_home BOOLEAN NOT NULL, 
	enrollment_mode VARCHAR(16) DEFAULT 'approval' NOT NULL, 
	open_permissions JSONB DEFAULT '["contribute"]' NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	revoked_at TIMESTAMP WITH TIME ZONE, 
	leader_member_id UUID, 
	leader_appointment JSONB, 
	removed_at TIMESTAMP WITH TIME ZONE, 
	former_name VARCHAR(64), 
	PRIMARY KEY (id), 
	CONSTRAINT ck_swarms_status CHECK (status IN ('active', 'revoked', 'removed')), 
	CONSTRAINT ck_swarms_enrollment_mode CHECK (enrollment_mode IN ('approval', 'invite', 'open')), 
	UNIQUE (name), 
	UNIQUE (public_key), 
	FOREIGN KEY(leader_member_id) REFERENCES members (id)
);

CREATE TABLE tokens (
	id UUID NOT NULL, 
	member_id UUID NOT NULL, 
	token_hash BYTEA NOT NULL, 
	permissions JSONB NOT NULL, 
	remote_ip VARCHAR(64), 
	issued_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	revoked_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(member_id) REFERENCES members (id), 
	UNIQUE (token_hash)
);

CREATE INDEX idx_tokens_member ON tokens (member_id);

CREATE TABLE dataset_reads (
	id BIGSERIAL NOT NULL, 
	member_id UUID NOT NULL, 
	dataset_id UUID NOT NULL, 
	version INTEGER NOT NULL, 
	item_key VARCHAR(200) NOT NULL, 
	cycle UUID, 
	source VARCHAR(16) NOT NULL, 
	ts TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_dataset_reads_source CHECK (source IN ('served', 'reported')), 
	FOREIGN KEY(member_id) REFERENCES members (id), 
	FOREIGN KEY(dataset_id) REFERENCES datasets (id)
);

CREATE INDEX idx_dataset_reads_dataset ON dataset_reads (dataset_id);

CREATE INDEX idx_dataset_reads_member_ts ON dataset_reads (member_id, ts);

CREATE TABLE dataset_versions (
	id BIGSERIAL NOT NULL, 
	dataset_id UUID NOT NULL, 
	version INTEGER NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	manifest_hash VARCHAR(64), 
	item_count INTEGER NOT NULL, 
	size_bytes BIGINT NOT NULL, 
	source_url TEXT, 
	snapshot_at TIMESTAMP WITH TIME ZONE, 
	approved_by VARCHAR(64), 
	approved_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_dataset_versions_version UNIQUE (dataset_id, version), 
	CONSTRAINT ck_dataset_versions_status CHECK (status IN ('pending', 'approved', 'withdrawn')), 
	FOREIGN KEY(dataset_id) REFERENCES datasets (id)
);

CREATE TABLE enrollment_swarm_requests (
	member_id UUID NOT NULL, 
	swarm_id VARCHAR(64) NOT NULL, 
	requested_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (member_id), 
	FOREIGN KEY(member_id) REFERENCES members (id), 
	FOREIGN KEY(swarm_id) REFERENCES swarms (id)
);

CREATE TABLE invites (
	id UUID NOT NULL, 
	swarm_id VARCHAR(64) NOT NULL, 
	code_hash VARCHAR(64) NOT NULL, 
	uses_left INTEGER NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE, 
	role VARCHAR(16) DEFAULT 'member' NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(swarm_id) REFERENCES swarms (id), 
	UNIQUE (code_hash)
);

CREATE INDEX idx_invites_swarm ON invites (swarm_id);

CREATE TABLE record_payloads (
	record_id BIGINT NOT NULL, 
	payload_raw BYTEA NOT NULL, 
	body JSONB NOT NULL, 
	size INTEGER NOT NULL, 
	PRIMARY KEY (record_id), 
	FOREIGN KEY(record_id) REFERENCES records (id)
);

CREATE TABLE record_provenance (
	record_id BIGINT NOT NULL, 
	swarm_id VARCHAR(64), 
	relay_member_id UUID, 
	received_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (record_id), 
	FOREIGN KEY(record_id) REFERENCES records (id), 
	FOREIGN KEY(swarm_id) REFERENCES swarms (id), 
	FOREIGN KEY(relay_member_id) REFERENCES members (id)
);

CREATE INDEX idx_record_provenance_relay ON record_provenance (relay_member_id);

CREATE INDEX idx_record_provenance_swarm ON record_provenance (swarm_id);

CREATE TABLE swarm_members (
	id BIGSERIAL NOT NULL, 
	swarm_id VARCHAR(64) NOT NULL, 
	member_id UUID NOT NULL, 
	role VARCHAR(16) NOT NULL, 
	joined_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	left_at TIMESTAMP WITH TIME ZONE, 
	appointment JSONB, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_swarm_members_role CHECK (role IN ('hub', 'member', 'observer')), 
	FOREIGN KEY(swarm_id) REFERENCES swarms (id), 
	FOREIGN KEY(member_id) REFERENCES members (id)
);

CREATE INDEX idx_swarm_members_swarm ON swarm_members (swarm_id);

CREATE UNIQUE INDEX uq_swarm_members_hub ON swarm_members (swarm_id) WHERE role = 'hub' AND left_at IS NULL;

CREATE UNIQUE INDEX uq_swarm_members_open ON swarm_members (member_id) WHERE left_at IS NULL;

CREATE TABLE dataset_items (
	id BIGSERIAL NOT NULL, 
	version_id BIGINT NOT NULL, 
	key VARCHAR(200) NOT NULL, 
	media_type VARCHAR(100) NOT NULL, 
	size_bytes BIGINT NOT NULL, 
	sha256 VARCHAR(64), 
	tier VARCHAR(16) NOT NULL, 
	text TEXT, 
	meta JSONB, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_dataset_items_key UNIQUE (version_id, key), 
	CONSTRAINT ck_dataset_items_tier CHECK (tier IN ('text', 'large', 'external')), 
	FOREIGN KEY(version_id) REFERENCES dataset_versions (id)
);

CREATE INDEX idx_dataset_items_sha256 ON dataset_items (sha256);

CREATE TABLE dataset_uploads (
	id UUID NOT NULL, 
	version_id BIGINT NOT NULL, 
	key VARCHAR(200) NOT NULL, 
	filename TEXT NOT NULL, 
	size_bytes BIGINT NOT NULL, 
	received_bytes BIGINT NOT NULL, 
	created_by VARCHAR(64) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(version_id) REFERENCES dataset_versions (id)
);

COMMIT;
